from dataclasses import dataclass, field
from typing import Dict

@dataclass(frozen=True)
class TrieNode:
    is_end: bool = False
    children: Dict[str, 'TrieNode'] = field(default_factory=dict)

def insert(root: TrieNode, word: str) -> TrieNode:
    return root

